// Frontier v2 entry point for shared/world/templates.js. The 768 x 80 x 768
// river valley is generated by shared/world/frontier-sites/generate.js from
// the pure terrain in shared/world/frontier-terrain.js.
import { generateFrontierV2Into } from './frontier-sites/generate.js';

/** Fill `blocks` (y/z/x) with the complete Frontier world. */
export function generateFrontierInto(world, blocks, heights) {
  generateFrontierV2Into(world, blocks, heights);
}
